"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[53190],{53254:e=>{e.exports=JSON.parse('{"label":"dapps","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/tags/dapps","allTagsPath":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/tags","count":11,"items":[{"id":"version-0.8/components","title":"Components","description":"As explained in the previous section, the Cartesi Rollups framework achieves scalability by moving the bulk of the computation outside the blockchain, using the ledger as a data source but not as an execution environment. As such, the solution contains both on-chain (L1) and off-chain (L2) components.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/components"},{"id":"version-0.8/build-dapps/create-dapp","title":"Create your first dApp","description":"Once you learned how to run a simple example, it is now time to create one of your own. In order to do this, we will make use of the dApp template available in Cartesi\'s rollups-examples Github repository. Once again, make sure you have installed all the necessary requirements before proceeding.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/build-dapps/create-dapp"},{"id":"version-0.8/dapp-architecture","title":"dApp architecture","description":"Borrowing from familiar mainstream terminology, from a developer\u2019s point of view a Cartesi dApp is developed by implementing two main components: a front-end and a back-end.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/dapp-architecture"},{"id":"version-0.8/dapp-life-cycle","title":"dApp life cycle","description":"Now that we have described the architecture of a Cartesi dApp and how the front-end and back-end communicate with the Cartesi Rollups framework, let\u2019s step back a bit to discuss how a dApp can be implemented in practice.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/dapp-life-cycle"},{"id":"version-0.8/build-dapps/deploying-dapps","title":"Deploying dApps","description":"Please check the full documentation for deploying Rollups dApps to Cartesi\'s cloud-based execution infrastructure.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/build-dapps/deploying-dapps"},{"id":"version-0.8/build-dapps/requirements","title":"General requirements","description":"To start developing applications using Cartesi Rollups, first make sure that the packages listed in this section are all installed and working in your system. The instructions listed below should be enough to turn a fresh copy of the latest Ubuntu LTS distribution into a fully fledged Cartesi development environment.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/build-dapps/requirements"},{"id":"version-0.8/overview","title":"Overview","description":"The combination of an Optimistic Rollups framework and the Cartesi Machine Emulator enables the development of smart contracts and dApps using any package or library that is available for Linux. This allows developers to break free from the scalability limitations of the Ethereum Virtual Machine (EVM), and brings the rise of a new blockchain era to handle real-life and complex use-cases.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/overview"},{"id":"version-0.8/build-dapps/overview","title":"Overview of building dApps","description":"Navigate to our Quick Start tutorial if you want to build dApps now!","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/build-dapps/overview"},{"id":"version-0.8/build-dapps/run-dapp","title":"Quick Start","description":"This article explains how to build and interact with a minimalistic Cartesi Rollups application.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/build-dapps/run-dapp"},{"id":"version-0.8/http-api","title":"Rollups HTTP APIs","description":"In a Cartesi dApp, the front-end and back-end parts of the application communicate with each other through the Rollups framework via a set of HTTP APIs.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/http-api"},{"id":"version-0.8/build-dapps/dapp-host-mode","title":"Run back-end in Host Mode","description":"When developing an application, it is often important to easily test and debug it. For that matter, it is possible to run the Cartesi Rollups environment in host mode, so that the dApp\'s back-end can be executed directly on the host machine, allowing it to be debugged using regular development tools such as an IDE.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/0.8/build-dapps/dapp-host-mode"}]}')}}]);